%[text] # Demo 6 - DE Analysis and Marker Gene Identification Functions
%[text] ## Load example data set, X
cdgea; % set working directory
load(pkg.i_exampledata('markergeneident_demo.mat'), 'X', 'genelist', 's_tsne');
% s_tsne is precomputed tSNE embedding
%%
%[text] ## Automatically cluster cells and explore cell type
figure;
gui.sc_celltypeexplorer_auto(X, genelist, s_tsne, "species", "mouse");
%%
%[text] ## Show result of manually brushing cells and exploring cell type
%[text] To generate the figure: (1) run gui.sc\_celltypeexplorer(X,genelist,s\_tsne,"species","mouse") (2) brush and select cell cluster
openfig(pkg.i_exampledata('markergeneident_demo.fig'));
%%
%[text] ## Group cells into clusters (k=6)
figure;
rng(1234)
cluster_kmedoids=sc_cluster_s(s_tsne, 6, 'type', 'kmedoids', 'plotit', true);
%%
%[text] ## Identify marker genes for cluster \#4 against other clusters
gmarkers = sc_pickmarkers(X, genelist, cluster_kmedoids, 9);
gmarkers = gmarkers{4};
%%
%[text] ## Show expression level of top 9 marker genes
figure;
for k=1:9
    g = gmarkers(k);
    subplot(3,3,k)
    grp = log1p(X(genelist==g,:));
    scatter3(s_tsne(:,1), s_tsne(:,2), s_tsne(:,3), 10, grp, 'filled');
    title(g)
end
subplot(3, 3, 1)
view([-25 90])
%%
%[text] ## Show expression level of the top marker gene
figure;
g = gmarkers(5);
sc_scattermarker(X, genelist, s_tsne, g);
% sc_stemscatter(s_tsne(:,1), s_tsne(:,2), log1p(X(genelist==g,:)));
title(g)
view([-31.03 77.60])
%%
%[text] ## Determine cell type for each cluster using marker genes (collected by PanglaoDB)
Tct = run.ml_alona(X, genelist, cluster_kmedoids, 'species', 'mouse')
%%
%[text] ## Another demo with example data of mouse pancreas cells
load(pkg.i_exampledata('new_example_sce.mat'), 'sce');
gui.sc_celltypeexplorer(sce.X, sce.g, sce.s, "species", "mouse");
pause(3)
%%
%[text] ## Use the SCGEATOOL interactive tool
%[text] 
scgeatool(sce)
%[text] 
%[text] ![](text:image:6bd9)
%[text] ## The End

